package com.aaliyun.leadnews.article.service;import com.aaliyun.leadnews.article.domain.Channel;import com.aaliyun.leadnews.article.mapper.ChannelMapper;import com.aaliyun.leadnews.common.api.CommonErrorCode;import com.aaliyun.leadnews.common.context.UserContext;import com.aaliyun.leadnews.common.exception.BusinessException;import com.aaliyun.leadnews.model.foundation.ChannelDTO;import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import org.springframework.dao.DuplicateKeyException;import org.springframework.stereotype.Service;import java.util.*;
@Service public class ChannelService {private final ChannelMapper mapper;public ChannelService(ChannelMapper m){mapper=m;}public List<ChannelDTO> all(){guard();return mapper.selectList(new LambdaQueryWrapper<Channel>().eq(Channel::getDeleted,false).orderByAsc(Channel::getOrd)).stream().map(this::dto).toList();}public ChannelDTO create(ChannelDTO d){guard();Channel c=new Channel();apply(c,d);try{mapper.insert(c);}catch(DuplicateKeyException e){throw new BusinessException(40900,"Channel name already exists");}return dto(c);}public ChannelDTO update(Long id,ChannelDTO d){guard();Channel c=require(id);apply(c,d);try{mapper.updateById(c);}catch(DuplicateKeyException e){throw new BusinessException(40900,"Channel name already exists");}return dto(c);}public ChannelDTO status(Long id,String s){guard();if(!Set.of("ENABLED","DISABLED").contains(s))throw new BusinessException(CommonErrorCode.VALIDATION);Channel c=require(id);c.setStatus(s);mapper.updateById(c);return dto(c);}public void delete(Long id){guard();mapper.deleteById(require(id));}private Channel require(Long id){Channel c=mapper.selectById(id);if(c==null)throw new BusinessException(40400,"Channel not found");return c;}private void apply(Channel c,ChannelDTO d){c.setName(d.name());c.setDescription(d.description());c.setStatus(d.status());c.setOrd(d.ord());}private ChannelDTO dto(Channel c){return new ChannelDTO(c.getId(),c.getName(),c.getDescription(),c.getStatus(),c.getOrd(),c.getCreatedTime(),c.getUpdatedTime());}private void guard(){if(!UserContext.isInternal()||!UserContext.isType("ADMIN"))throw new BusinessException(CommonErrorCode.AUTH_FORBIDDEN);}}
